:root {
  --ink: #29463a;
  --ink-soft: #476657;
  --muted: #7c8e81;
  --green: #5e8f68;
  --green-deep: #3e6c50;
  --green-light: #e8f1e1;
  --cream: #fffdf7;
  --paper: #f6f1e5;
  --orange: #efa959;
  --orange-deep: #d98a39;
  --coral: #e78272;
  --line: #e5e4d8;
  --shadow: 0 18px 50px rgba(67, 82, 52, .14);
  font-family: "DM Sans", sans-serif;
  color: var(--ink);
  background: var(--paper);
  font-synthesis: none;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  overflow: hidden;
  background:
    radial-gradient(circle at 12% 8%, rgba(226, 240, 210, .8), transparent 28%),
    radial-gradient(circle at 88% 92%, rgba(250, 227, 187, .55), transparent 30%),
    var(--paper);
}

button, a { -webkit-tap-highlight-color: transparent; }
button { font: inherit; cursor: pointer; }
button:focus-visible, a:focus-visible { outline: 3px solid #f0b35e; outline-offset: 3px; }

.app-shell {
  width: min(1500px, 100%);
  height: 100dvh;
  margin: 0 auto;
  padding: 0 34px;
  display: flex;
  flex-direction: column;
}

/* ── Top bar ───────────────────────────────────────────────────────── */
.topbar {
  height: 82px;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  color: var(--ink);
  font-family: "Fredoka", sans-serif;
  font-size: 22px;
  line-height: .9;
  letter-spacing: -.7px;
  text-decoration: none;
  white-space: nowrap;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 13px;
  background: #dcebd3;
  color: #61945b;
  font-size: 26px;
  transform: rotate(-8deg);
}

.brand-bold { color: #679567; font-weight: 700; }
.brand small {
  display: block;
  margin-top: 6px;
  color: #91a08f;
  font: 700 8px "DM Sans", sans-serif;
  letter-spacing: 1.55px;
}

.hud-stats { display: flex; gap: 9px; }

.stat-pill {
  height: 48px;
  min-width: 98px;
  padding: 4px 13px;
  border: 1px solid rgba(229, 228, 216, .75);
  border-radius: 15px;
  background: rgba(255, 255, 255, .85);
  box-shadow: 0 4px 16px rgba(52, 69, 41, .05);
  display: grid;
  grid-template-columns: 24px auto;
  grid-template-rows: 24px 12px;
  align-items: center;
}

.stat-pill .stat-icon { grid-row: 1 / 3; font-size: 17px; filter: saturate(.8); }
.stat-pill > span:nth-child(2) { font: 700 17px "Fredoka", sans-serif; line-height: 1; }
.stat-pill small { color: #94a095; font-size: 8px; font-weight: 700; letter-spacing: 1px; }
.stat-pill.tips > span:nth-child(2) { color: #b67b32; }

.top-actions { display: flex; align-items: center; gap: 8px; }

.icon-button, .sound-button, .shop-button {
  height: 42px;
  border-radius: 13px;
  border: 1px solid var(--line);
  background: rgba(255, 253, 247, .9);
  color: #62776a;
  padding: 0 13px;
  font-size: 12px;
  font-weight: 700;
  transition: transform .15s ease, background .15s ease, border-color .15s ease;
}

.icon-button:hover, .sound-button:hover { background: #fff; border-color: #d5d8c9; transform: translateY(-1px); }
.sound-button { width: 42px; padding: 0; font-size: 16px; }
.shop-button {
  background: #345f46;
  color: #fffdf4;
  border-color: #345f46;
  box-shadow: 0 8px 20px rgba(52, 95, 70, .18);
}
.shop-button:hover { background: #294f3a; transform: translateY(-1px); }

/* ── Main layout ───────────────────────────────────────────────────── */
.game-layout {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 310px;
  gap: 20px;
  padding: 18px 0;
}

.world-card {
  position: relative;
  min-height: 0;
  overflow: hidden;
  border-radius: 28px;
  background: #a9cf8b;
  box-shadow: var(--shadow);
