.location-chip small { color: #8a9c8b; font-size: 8px; letter-spacing: 1px; }
.location-dot { width: 7px; height: 7px; border-radius: 50%; background: #77ad68; box-shadow: 0 0 0 4px rgba(119, 173, 104, .17); }

.quest-card {
  position: absolute;
