  font-size: 11px;
  font-weight: 700;
  letter-spacing: .15px;
  box-shadow: 0 8px 24px rgba(37, 58, 43, .15);
  backdrop-filter: blur(8px);
  pointer-events: none;
  transition: opacity .35s ease, transform .35s ease;
}
.aim-hint.hidden { opacity: 0; transform: translate(-50%, -42%); }
.aim-dot { width: 7px; height: 7px; border-radius: 50%; background: #f3c878; box-shadow: 0 0 0 4px rgba(243, 200, 120, .2); }

.feedback {
  position: absolute;
  z-index: 4;
  max-width: 280px;
  padding: 8px 13px;
  border-radius: 12px;
  background: rgba(45, 72, 53, .92);
  color: #fffde9;
  font: 700 12px "DM Sans", sans-serif;
  text-align: center;
  box-shadow: 0 8px 22px rgba(38, 60, 42, .24);
  opacity: 0;
  transform: translate(-50%, 4px) scale(.94);
  pointer-events: none;
}
.feedback.show { animation: floatUp 1.25s ease both; }
@keyframes floatUp {
  0% { opacity: 0; transform: translate(-50%, 8px) scale(.92); }
  16% { opacity: 1; transform: translate(-50%, 0) scale(1); }
  72% { opacity: 1; transform: translate(-50%, -8px) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -25px) scale(.98); }
}

.scene-legend {
  position: absolute;
  left: 18px;
  bottom: 18px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid rgba(255, 255, 255, .55);
  border-radius: 999px;
  background: rgba(255, 253, 241, .68);
  color: #6c816d;
  font-size: 9px;
  font-weight: 700;
  backdrop-filter: blur(6px);
  pointer-events: none;
}
.scene-legend b { color: #3e684b; }
.legend-dot { color: #9fae9e; }

.joystick { display: none; }
.toss-button { display: none; }

/* ── Side panel ────────────────────────────────────────────────────── */
.side-panel {
  min-height: 0;
  padding: 21px 20px 17px;
  border: 1px solid rgba(229, 228, 216, .8);
  border-radius: 26px;
  background: rgba(255, 253, 247, .92);
  box-shadow: 0 12px 35px rgba(61, 74, 48, .07);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.panel-top { display: flex; align-items: center; justify-content: space-between; }
.panel-kicker { margin: 0; color: #93a08e; font-size: 8px; font-weight: 800; letter-spacing: 1.55px; }
.crew-badge {
  display: grid;
  place-items: center;
  min-width: 25px;
  height: 25px;
  padding: 0 8px;
  border-radius: 9px;
  background: #eaf1e1;
  color: #4f7d5d;
  font: 700 12px "Fredoka", sans-serif;
}

.side-panel h2 { margin: 13px 0 5px; color: #315541; font: 600 23px/1.05 "Fredoka", sans-serif; letter-spacing: -.4px; }
.panel-copy { margin: 0 0 15px; color: #829183; font-size: 11px; line-height: 1.55; }

.income-card {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 12px;
  border: 1px solid #f0e7cd;
  border-radius: 16px;
  background: linear-gradient(135deg, #fff9e7, #fcf3d8);
  color: #5d5538;
}
.income-icon { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 12px; background: #fff1b8; font-size: 18px; }
.income-card b { display: block; color: #7d612c; font: 600 15px "Fredoka", sans-serif; }
.income-card small { display: block; margin-top: 1px; color: #a29370; font-size: 9px; font-weight: 600; }
.income-spark { margin-left: auto; color: #e5b957; font-size: 17px; }

.rank-card { margin: 12px 1px 14px; }
.rank-line { display: flex; justify-content: space-between; color: #8b988a; font-size: 9px; font-weight: 700; }
.rank-line b { color: #56755d; }
.xp-track { height: 6px; margin-top: 6px; overflow: hidden; border-radius: 99px; background: #e9eadf; }
.xp-track span { display: block; width: 0; height: 100%; border-radius: inherit; background: #7cac76; transition: width .35s ease; }

.crew-list { flex: 1; min-height: 50px; overflow-y: auto; padding-right: 3px; scrollbar-width: thin; scrollbar-color: #d8dfcd transparent; }
.crew-empty { display: grid; place-items: center; min-height: 96px; padding: 14px; border: 1px dashed #dce2d4; border-radius: 16px; color: #9aa898; font-size: 10px; text-align: center; line-height: 1.5; }
.crew-empty span { display: block; margin-bottom: 5px; font-size: 23px; opacity: .7; }
.crew-row { display: flex; align-items: center; gap: 10px; padding: 8px 7px; border-radius: 12px; }
.crew-row + .crew-row { border-top: 1px solid #f0f0e8; border-radius: 0 0 12px 12px; }
.crew-row:hover { background: #f8f7ef; }
.crew-avatar { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 11px; background: #edf3e4; font-size: 20px; }
.crew-copy { min-width: 0; flex: 1; }
.crew-copy b { display: block; color: #4a6652; font-size: 11px; }
.crew-copy small { display: block; margin-top: 1px; color: #9aa79a; font-size: 8px; font-weight: 600; }
.crew-tip { color: #b38b47; font-size: 9px; font-weight: 800; white-space: nowrap; }

.next-upgrade {
  margin-top: 10px;
  padding: 10px 11px;
  border: 1px solid #e9e9dd;
  border-radius: 14px;
  background: #fbfaf4;
}
.next-upgrade .upgrade-label { display: flex; align-items: center; gap: 7px; color: #8e9a8b; font-size: 8px; font-weight: 800; letter-spacing: .9px; }
.next-upgrade .upgrade-label span { font-size: 15px; }
.next-upgrade b { display: block; margin: 4px 0 2px; color: #4b6754; font: 600 13px "Fredoka", sans-serif; }
.next-upgrade small { color: #9ca79a; font-size: 9px; }

.wide-button {
  width: 100%;
  height: 40px;
  margin-top: 9px;
  border: 0;
  border-radius: 12px;
  background: #e9f0e1;
  color: #4d7659;
  font-size: 11px;
  font-weight: 800;
  transition: background .15s ease, transform .15s ease;
}
.wide-button span { margin-left: 4px; color: #84a17f; }
.wide-button:hover { background: #dfead5; transform: translateY(-1px); }

.text-button { margin-top: 7px; border: 0; background: none; color: #97a397; font-size: 9px; font-weight: 700; text-decoration: underline; text-underline-offset: 3px; }
.text-button:hover { color: #617d67; }

/* ── Snack dock ────────────────────────────────────────────────────── */
.bottom-dock {
  height: 102px;
  flex: none;
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr) auto;
  align-items: center;
  gap: 18px;
  padding: 10px 0 16px;
  border-top: 1px solid var(--line);
}

.dock-intro { display: flex; flex-direction: column; }
.dock-kicker { margin-bottom: 3px; color: #a1aa9a; font-size: 8px; font-weight: 800; letter-spacing: 1.25px; }
.dock-intro b { color: #3b5e48; font: 600 18px "Fredoka", sans-serif; }
.dock-intro small { margin-top: 1px; color: #99a497; font-size: 9px; }

.snack-options { display: flex; align-items: center; gap: 9px; min-width: 0; }

.snack-card {
  position: relative;
  flex: 1 1 0;
  max-width: 142px;
  min-width: 76px;
  height: 67px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 12px 9px 9px;
  border: 1px solid #e8e6da;
  border-radius: 17px;
  background: rgba(255, 253, 247, .86);
  color: #65776a;
  text-align: left;
  transition: transform .16s ease, border-color .16s ease, background .16s ease, box-shadow .16s ease;
}

.snack-card:hover { transform: translateY(-2px); border-color: #d9ddcb; background: #fffdf7; }
.snack-card.selected { border-color: #88ad79; background: #f7fbf0; box-shadow: 0 0 0 2px rgba(130, 171, 114, .2), 0 7px 18px rgba(67, 100, 56, .09); }
.snack-hotkey { position: absolute; top: 5px; right: 7px; color: #b1b9a8; font-size: 7px; font-weight: 800; }
.snack-emoji { display: grid; place-items: center; width: 39px; height: 39px; flex: none; border-radius: 12px; background: #f2f2e6; font-size: 24px; }
.snack-card.selected .snack-emoji { background: #e8f1dc; }
.snack-label { display: block; font-size: 10px; font-weight: 800; line-height: 1.15; }
.snack-card.selected .snack-label { color: #3e6b4c; }

.dock-controls { display: flex; align-items: center; gap: 14px; }
.throw-counter { display: grid; grid-template-columns: 15px auto; grid-template-rows: 20px 10px; align-items: center; min-width: 58px; }
.throw-star { grid-row: 1 / 3; color: #e6a858; font-size: 13px; }
.throw-counter > span:nth-child(2) { color: #4b6754; font: 700 16px "Fredoka", sans-serif; }
.throw-counter small { color: #a3ac9f; font-size: 7px; font-weight: 800; letter-spacing: .8px; }

.mission-button {
  height: 39px;
  padding: 0 13px;
  border: 1px solid #e5e4d7;
  border-radius: 12px;
  background: #fffdf7;
  color: #77877a;
  font-size: 10px;
  font-weight: 700;
}
.mission-button span { margin-right: 4px; color: #97a594; }
.mission-button:hover { background: #fff; border-color: #d4dac8; }

/* ── Modals ────────────────────────────────────────────────────────── */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  padding: 22px;
  background: rgba(37, 55, 41, .48);
  backdrop-filter: blur(6px);
}
.modal-backdrop[hidden] { display: none; }

.modal-card {
  position: relative;
  width: min(870px, 100%);
  max-height: min(88dvh, 820px);
  overflow-y: auto;
  padding: 29px 30px 25px;
  border: 1px solid rgba(255, 255, 255, .7);
  border-radius: 30px;
  background: #fffdf7;
  box-shadow: 0 28px 90px rgba(32, 53, 36, .3);
  animation: modalIn .24s cubic-bezier(.2, .8, .3, 1) both;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(14px) scale(.98); } to { opacity: 1; transform: none; } }

.modal-close {
  position: absolute;
  top: 16px;
  right: 17px;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid #ecebe1;
  border-radius: 11px;
  background: #faf9f2;
  color: #829083;
  font-size: 21px;
  line-height: 1;
}
.modal-close:hover { background: #f1f2e9; }

.modal-heading { display: grid; grid-template-columns: 58px minmax(0, 1fr) auto; gap: 14px; align-items: start; padding-right: 38px; }
.modal-flower { display: grid; place-items: center; width: 58px; height: 58px; border-radius: 18px; background: #edf4e4; font-size: 29px; transform: rotate(-4deg); }
.modal-heading h2 { margin: 4px 0 5px; color: #2f523e; font: 600 28px/1.05 "Fredoka", sans-serif; letter-spacing: -.6px; }
.modal-heading p:not(.panel-kicker) { max-width: 480px; margin: 0; color: #859285; font-size: 11px; line-height: 1.55; }

.modal-wallet {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 41px;
  padding: 0 13px;
  border: 1px solid #f0e4c4;
  border-radius: 13px;
  background: #fff7e1;
  color: #7c612f;
  font: 700 17px "Fredoka", sans-serif;
  white-space: nowrap;
}
.modal-wallet span { font-size: 16px; }
.guide-total { min-width: 100px; padding: 6px 12px; border: 1px solid #e5eadd; border-radius: 13px; background: #f6f9f0; text-align: center; }
.guide-total b { display: block; color: #4c7357; font: 600 21px "Fredoka", sans-serif; line-height: 1; }
.guide-total small { color: #9baa9a; font-size: 7px; font-weight: 800; letter-spacing: .7px; }

.shop-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 22px;
}

.upgrade-card {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  padding: 14px;
  border: 1px solid #eae9de;
  border-radius: 18px;
  background: #fbfaf4;
  transition: border-color .15s ease, background .15s ease;
}
.upgrade-card:hover { border-color: #dfe4d3; background: #fffef9; }
.upgrade-card.maxed { background: #f7faf1; }
.upgrade-icon { display: grid; place-items: center; width: 46px; height: 46px; border-radius: 14px; background: #edf3e4; font-size: 23px; }
.upgrade-info { min-width: 0; }
.upgrade-title { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.upgrade-title b { color: #43614d; font: 600 14px "Fredoka", sans-serif; }
.upgrade-title span { color: #a0aa9b; font-size: 8px; font-weight: 800; letter-spacing: .4px; white-space: nowrap; }
.upgrade-info p { margin: 3px 0 8px; color: #8d998c; font-size: 9px; line-height: 1.4; }
.upgrade-levels { display: flex; gap: 4px; margin-bottom: 9px; }
.upgrade-levels i { width: 17px; height: 4px; border-radius: 99px; background: #e5e8dd; }
.upgrade-levels i.on { background: #86ad78; }
.upgrade-buy {
  width: 100%;
  height: 31px;
  border: 1px solid #d9e3d2;
  border-radius: 9px;
  background: #f2f7ec;
  color: #557b5f;
  font-size: 9px;
  font-weight: 800;
}
.upgrade-buy:hover:not(:disabled) { background: #e8f1df; }
.upgrade-buy:disabled { cursor: default; opacity: .55; }
.upgrade-card.maxed .upgrade-buy { border-color: #dbe8d2; background: #eaf4e2; color: #5f8b65; opacity: 1; }

.shop-footer { display: flex; align-items: center; gap: 8px; margin-top: 14px; padding: 10px 12px; border-radius: 12px; background: #f8f6ec; color: #929b8d; font-size: 9px; }
.shop-footer span { font-size: 14px; }

.guide-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 9px; margin-top: 21px; }
.guide-animal { display: flex; align-items: center; gap: 10px; padding: 11px; border: 1px solid #eae9de; border-radius: 15px; background: #fbfaf4; }
.guide-animal.locked { opacity: .55; filter: grayscale(.8); }
.guide-avatar { display: grid; place-items: center; width: 38px; height: 38px; flex: none; border-radius: 12px; background: #edf3e4; font-size: 23px; }
.guide-copy { min-width: 0; flex: 1; }
.guide-copy b { display: block; color: #486451; font-size: 10px; }
.guide-copy small { display: block; margin-top: 2px; color: #99a597; font-size: 8px; }
.guide-count { color: #6c8d6f; font: 700 12px "Fredoka", sans-serif; }
.guide-count.empty { color: #b6bdb1; font-weight: 500; }

.controls-card { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 16px; padding-top: 16px; border-top: 1px solid #efeee5; }
.controls-card > div { display: flex; flex-direction: column; gap: 3px; }
.controls-card b { color: #56715e; font-size: 9px; }
.controls-card small { color: #9ba59a; font-size: 8px; }
.key-group { display: flex; gap: 3px; margin-bottom: 3px; }
.key-group kbd { display: grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border: 1px solid #dfe4d7; border-radius: 5px; background: #f8f9f2; color: #718172; font: 700 8px "DM Sans", sans-serif; box-shadow: 0 1px 0 #e5e8dd; }

.help-card { width: min(480px, 100%); padding: 32px; }
.help-card .modal-flower { margin-bottom: 14px; }
.help-card h2 { margin: 5px 0 8px; color: #2f523e; font: 600 30px/1.05 "Fredoka", sans-serif; letter-spacing: -.6px; }
.help-card > p:not(.panel-kicker) { margin: 0 0 20px; color: #849184; font-size: 11px; line-height: 1.6; }
.guide-row { display: flex; align-items: center; gap: 12px; padding: 10px 0; border-top: 1px solid #efeee5; }
.guide-row > span:first-child { display: grid; place-items: center; width: 35px; height: 35px; border-radius: 11px; background: #f4f4e9; font-size: 18px; }
.guide-row b { display: block; color: #4e6c57; font-size: 11px; }
.guide-row small { display: block; margin-top: 2px; color: #98a397; font-size: 9px; line-height: 1.35; }
.primary-button { width: 100%; height: 47px; margin-top: 18px; border: 0; border-radius: 13px; background: #3d6a50; color: #fffdf4; font-size: 11px; font-weight: 800; box-shadow: 0 9px 22px rgba(48, 89, 64, .2); }
.primary-button span { margin-left: 4px; color: #bcd7ad; }
.primary-button:hover { background: #315c44; }

/* ── Toast ─────────────────────────────────────────────────────────── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 126px;
  z-index: 30;
  max-width: min(430px, calc(100vw - 36px));
  padding: 11px 18px;
  border: 1px solid rgba(255, 255, 255, .45);
  border-radius: 999px;
  background: rgba(43, 71, 52, .94);
  color: #fffce8;
  font-size: 11px;
  font-weight: 700;
  text-align: center;
  box-shadow: 0 12px 30px rgba(31, 50, 37, .24);
  opacity: 0;
  transform: translate(-50%, 10px);
  pointer-events: none;
  transition: opacity .22s ease, transform .22s ease;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

@media (max-width: 1120px) {
  .app-shell { padding: 0 22px; }
  .game-layout { grid-template-columns: minmax(0, 1fr) 280px; gap: 16px; }
  .dock-intro { display: none; }
  .bottom-dock { grid-template-columns: minmax(0, 1fr) auto; }
  .icon-button span { display: none; }
  .icon-button { width: 42px; padding: 0; }
}

@media (max-width: 860px) {
  body { overflow: hidden; }
  .app-shell { padding: 0 12px; height: 100dvh; }
  .topbar { height: 64px; gap: 8px; }
  .brand { font-size: 18px; gap: 7px; }
  .brand-mark { width: 32px; height: 32px; border-radius: 10px; font-size: 20px; }
  .brand small { display: none; }
  .brand-bold { display: inline; }
  .hud-stats { gap: 5px; }
  .stat-pill { height: 39px; min-width: 66px; padding: 3px 8px; grid-template-columns: 18px auto; grid-template-rows: 20px 10px; border-radius: 11px; }
  .stat-pill .stat-icon { font-size: 13px; }
  .stat-pill > span:nth-child(2) { font-size: 14px; }
  .stat-pill small { font-size: 6px; letter-spacing: .5px; }
  .stat-pill.rank { display: none; }
  .top-actions { gap: 5px; }
  .icon-button { width: 37px; height: 37px; padding: 0; border-radius: 11px; }
  .icon-button span { display: none; }
  .shop-button { width: 37px; height: 37px; padding: 0; border-radius: 11px; font-size: 14px; }
  .shop-button span { display: none; }
  .sound-button { width: 37px; height: 37px; border-radius: 11px; font-size: 14px; }

  .game-layout { display: block; padding: 8px 0 0; min-height: 0; }
  .world-card { height: 100%; min-height: 0; border-radius: 20px; box-shadow: 0 12px 32px rgba(67, 82, 52, .14); }
  .side-panel { display: none; }

  .location-chip { top: 10px; left: 10px; min-height: 25px; padding: 0 9px; font-size: 7px; gap: 5px; }
  .location-chip small { display: none; }
  .quest-card { top: 10px; right: 10px; width: 168px; padding: 10px 11px 9px; border-radius: 13px; }
  .quest-kicker { font-size: 6px; letter-spacing: 1px; }
  .quest-card b { font-size: 11px; line-height: 1.2; }
  .quest-track { height: 5px; margin: 7px 0 5px; }
  .quest-card small { font-size: 7px; }
  .aim-hint { top: auto; bottom: 88px; font-size: 9px; padding: 8px 12px; white-space: nowrap; }
  .aim-hint.hidden { transform: translate(-50%, 5px); }
  .throw-tip { display: none; }
  .scene-legend { display: none; }
  .feedback { font-size: 10px; padding: 7px 10px; max-width: 190px; }
  .interaction-prompt { bottom: 106px; font-size: 9px; }

  .joystick {
    display: block;
    position: absolute;
    left: 18px;
    bottom: 18px;
    width: 92px;
    height: 92px;
    border: 1px solid rgba(255, 255, 255, .5);
    border-radius: 50%;
    background: rgba(255, 253, 240, .2);
    box-shadow: inset 0 0 0 12px rgba(255, 253, 240, .1);
    backdrop-filter: blur(2px);
    touch-action: none;
    z-index: 5;
  }
  .joystick-ring { position: absolute; inset: 26px; border: 1px solid rgba(255, 255, 255, .42); border-radius: 50%; }
  .joystick-knob {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 42px;
    height: 42px;
    border: 1px solid rgba(255, 255, 255, .75);
    border-radius: 50%;
    background: rgba(255, 253, 239, .76);
    box-shadow: 0 5px 16px rgba(50, 72, 44, .18);
    transform: translate(-50%, -50%);
  }

  .toss-button {
    display: flex;
    align-items: center;
    gap: 5px;
    position: absolute;
    right: 18px;
    bottom: 28px;
    z-index: 5;
    height: 52px;
    padding: 0 18px;
    border: 1px solid rgba(255, 255, 255, .4);
    border-radius: 17px;
    background: rgba(50, 92, 65, .9);
    color: #fffce9;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: .4px;
    box-shadow: 0 9px 22px rgba(39, 65, 45, .22);
    backdrop-filter: blur(8px);
  }
  .toss-button span { color: #f1c477; font-size: 14px; }
  .toss-button:active { transform: scale(.96); }

  .bottom-dock {
    height: 96px;
    display: block;
    padding: 9px 0 10px;
    border-top: 0;
  }
  .dock-intro, .dock-controls { display: none; }
