const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 900, height: 600 } })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
const result = await page.evaluate(() => {
  const test = document.createElement('canvas')
  test.width = 700
  test.height = 460
  const t = test.getContext('2d')
  t.fillStyle = '#a1c980'
  t.fillRect(0, 0, 700, 460)
  const cases = [
    ['48px "Noto Color Emoji"', '#000'],
    ['38.28px "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif', 'rgba(255,255,255,.18)'],
    ['38px "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif', '#000'],
    ['38px "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif', 'rgba(255,255,255,.18)'],
    ['21px "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif', 'rgba(255,255,255,.18)'],
    ['48px "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif', '#f3e8d5'],
  ]
  cases.forEach(([font, color], i) => {
    const x = 100 + (i % 3) * 220
    const y = 100 + Math.floor(i / 3) * 180
    t.fillStyle = '#f3e8d5'
    t.beginPath(); t.arc(x, y, 45, 0, Math.PI * 2); t.fill()
    t.fillStyle = color
    t.font = font
    t.textAlign = 'center'
    t.textBaseline = 'middle'
    t.fillText('🐰', x, y)
  })
  return test.toDataURL()
})
writeFileSync('/tmp/opencode/emoji-sizes.png', Buffer.from(result.split(',')[1], 'base64'))
await browser.close()

