import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const errors = []

async function openPage(viewport) {
  const page = await browser.newPage({ viewport })
  page.on('pageerror', error => errors.push(`pageerror: ${error.message}`))
  page.on('console', message => {
    if (message.type() === 'error' && !message.text().includes('favicon')) errors.push(`console: ${message.text()}`)
  })
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.waitForFunction(() => window.__snackSafari?.state)
  await page.waitForTimeout(600)
  return page
}

const page = await openPage({ width: 1440, height: 900 })
const start = await page.evaluate(() => window.__snackSafari.state)
console.log('START', JSON.stringify(start))

// Movement
await page.keyboard.down('d')
await page.waitForTimeout(600)
await page.keyboard.up('d')
await page.waitForTimeout(200)
const moved = await page.evaluate(() => window.__snackSafari.state.player)
console.log('MOVED', JSON.stringify(moved), 'deltaX', Math.round(moved.x - start.player.x))

// Pick the nearest wild animal, select its favorite, and click it on canvas.
const target = await page.evaluate(() => {
  const api = window.__snackSafari
  const sorted = api.wild
    .map(animal => ({ animal, distance: Math.hypot(animal.x - api.player.x, animal.y - api.player.y) }))
    .sort((a, b) => a.distance - b.distance)
  const animal = sorted[0].animal
  api.selectFood(animal.species.food)
  const screen = api.screenPoint(animal)
  const rect = document.querySelector('#game-canvas').getBoundingClientRect()
  return {
    name: animal.species.name,
    species: animal.species.id,
    food: animal.species.food,
    distance: sorted[0].distance,
    x: rect.left + screen.x,
    y: rect.top + screen.y,
  }
})
console.log('TARGET', JSON.stringify(target))
await page.mouse.click(target.x, target.y)
await page.waitForTimeout(1500)
const afterTame = await page.evaluate(() => window.__snackSafari.state)
console.log('AFTER_TAME', JSON.stringify(afterTame))

// Passive income
await page.waitForTimeout(3300)
const afterTips = await page.evaluate(() => window.__snackSafari.state)
console.log('AFTER_TIPS', JSON.stringify(afterTips))

// Shop purchase
await page.click('#shop-button')
await page.waitForTimeout(350)
const shopVisible = await page.locator('#shop-modal').isVisible()
const coinsBefore = await page.evaluate(() => window.__snackSafari.state.coins)
const buy = page.locator('.upgrade-buy:not([disabled])').first()
const buyCount = await buy.count()
let buyLabel = ''
if (buyCount) {
  buyLabel = (await buy.textContent()).trim()
  await buy.click()
  await page.waitForTimeout(300)
}
const afterBuy = await page.evaluate(() => window.__snackSafari.state)
console.log('SHOP', JSON.stringify({ shopVisible, coinsBefore, buyCount, buyLabel, afterCoins: afterBuy.coins, upgrades: afterBuy.upgrades }))
await page.screenshot({ path: '/tmp/opencode/shop-open.png' })
await page.click('#shop-close')

// Guide
await page.click('#guide-button')
await page.waitForTimeout(250)
const guideTotal = await page.locator('#guide-total').textContent()
const guideCards = await page.locator('.guide-animal').count()
console.log('GUIDE', JSON.stringify({ guideTotal, guideCards }))
await page.screenshot({ path: '/tmp/opencode/guide-open.png' })
await page.click('#guide-close')

// Capture the played desktop state
await page.waitForTimeout(500)
await page.screenshot({ path: '/tmp/opencode/played-desktop.png' })

// Mobile interactions
const mobile = await openPage({ width: 390, height: 844 })
const mobileStart = await mobile.evaluate(() => window.__snackSafari.state)
const joystick = await mobile.locator('#joystick').boundingBox()
if (joystick) {
  const cx = joystick.x + joystick.width / 2
  const cy = joystick.y + joystick.height / 2
  await mobile.mouse.move(cx, cy)
  await mobile.mouse.down()
  await mobile.mouse.move(cx + 30, cy, { steps: 5 })
  await mobile.waitForTimeout(650)
  await mobile.mouse.up()
  await mobile.waitForTimeout(200)
}
const mobileMoved = await mobile.evaluate(() => window.__snackSafari.state.player)
const throwsBefore = (await mobile.evaluate(() => window.__snackSafari.state)).throws
await mobile.click('#toss-button')
await mobile.waitForTimeout(700)
const mobileAfter = await mobile.evaluate(() => window.__snackSafari.state)
console.log('MOBILE', JSON.stringify({
  start: mobileStart.player,
  moved: mobileMoved,
  deltaX: Math.round(mobileMoved.x - mobileStart.player.x),
  throwsBefore,
  throwsAfter: mobileAfter.throws,
  wild: mobileAfter.wild,
}))
await mobile.screenshot({ path: '/tmp/opencode/played-mobile.png' })

console.log('ERRORS', JSON.stringify(errors))
