import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const errors = []

async function openPage(viewport) {
  const page = await browser.newPage({ viewport })
  page.on('pageerror', error => errors.push(`pageerror: ${error.message}`))
  page.on('console', message => {
    if (message.type() === 'error' && !message.text().includes('favicon')) errors.push(`console: ${message.text()}`)
  })
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.waitForFunction(() => window.__snackSafari?.state)
  await page.waitForTimeout(700)
  return page
}

async function tameOne(page) {
  const target = await page.evaluate(() => {
    const api = window.__snackSafari
    const canvas = document.querySelector('#game-canvas')
    const rect = canvas.getBoundingClientRect()
    const quest = document.querySelector('.quest-card').getBoundingClientRect()
    const candidates = api.wild.map(animal => {
      const screen = api.screenPoint(animal)
      const pageX = rect.left + screen.x
      const pageY = rect.top + screen.y
      const underQuest = pageX > quest.left - 50 && pageX < quest.right + 50 && pageY > quest.top - 50 && pageY < quest.bottom + 50
      return { animal, screen, pageX, pageY, underQuest, distance: Math.hypot(animal.x - api.player.x, animal.y - api.player.y) }
    }).filter(item => !item.underQuest && item.screen.x > 90 && item.screen.x < rect.width - 90 && item.screen.y > 90 && item.screen.y < rect.height - 90)
      .sort((a, b) => a.distance - b.distance)
    if (!candidates.length) return null
    const chosen = candidates[0]
    api.selectFood(chosen.animal.species.food)
    return {
      name: chosen.animal.species.name,
      food: chosen.animal.species.food,
      x: chosen.pageX,
      y: chosen.pageY,
      distance: Math.round(chosen.distance),
    }
  })
  if (!target) return { ok: false, reason: 'no target' }
  const before = await page.evaluate(() => window.__snackSafari.state.crew)
  await page.mouse.click(target.x, target.y)
  await page.waitForTimeout(1300)
  let after = await page.evaluate(() => window.__snackSafari.state.crew)
  if (after === before) {
    await page.evaluate(() => window.__snackSafari.launchAtAim())
    await page.waitForTimeout(1300)
    after = await page.evaluate(() => window.__snackSafari.state.crew)
  }
  return { ok: after > before, target, crew: after }
}

const page = await openPage({ width: 1440, height: 900 })
console.log('START', JSON.stringify(await page.evaluate(() => window.__snackSafari.state)))

await page.keyboard.down('d')
await page.waitForTimeout(700)
await page.keyboard.up('d')
await page.waitForTimeout(200)
const moved = await page.evaluate(() => window.__snackSafari.state.player)
console.log('MOVEMENT', JSON.stringify(moved))

for (let index = 0; index < 3; index += 1) {
  const result = await tameOne(page)
  console.log('TAME', index + 1, JSON.stringify(result))
  await page.waitForTimeout(250)
}

const afterTames = await page.evaluate(() => window.__snackSafari.state)
console.log('AFTER_TAMES', JSON.stringify(afterTames))
await page.waitForTimeout(3400)
const afterTips = await page.evaluate(() => window.__snackSafari.state)
console.log('AFTER_TIPS', JSON.stringify(afterTips))
await page.screenshot({ path: '/home/runner/work/Throwfood/Throwfood/screenshots/play-desktop.png' })

await page.click('#shop-button')
await page.waitForTimeout(350)
const coinsBefore = await page.evaluate(() => window.__snackSafari.state.coins)
const buy = page.locator('.upgrade-buy:not([disabled])').first()
const buyCount = await buy.count()
if (buyCount) await buy.click()
await page.waitForTimeout(350)
const afterBuy = await page.evaluate(() => window.__snackSafari.state)
console.log('SHOP', JSON.stringify({ coinsBefore, buyCount, afterCoins: afterBuy.coins, upgrades: afterBuy.upgrades }))
await page.screenshot({ path: '/home/runner/work/Throwfood/Throwfood/screenshots/shop-desktop.png' })
await page.click('#shop-close')

await page.click('#guide-button')
await page.waitForTimeout(300)
console.log('GUIDE', JSON.stringify({
  total: await page.locator('#guide-total').textContent(),
  cards: await page.locator('.guide-animal').count(),
  crewRows: await page.locator('.crew-row').count(),
}))
await page.screenshot({ path: '/home/runner/work/Throwfood/Throwfood/screenshots/guide-desktop.png' })
await page.click('#guide-close')

const mobile = await openPage({ width: 390, height: 844 })
const mobileStart = await mobile.evaluate(() => window.__snackSafari.state)
const joystick = await mobile.locator('#joystick').boundingBox()
if (joystick) {
  const cx = joystick.x + joystick.width / 2
  const cy = joystick.y + joystick.height / 2
  await mobile.mouse.move(cx, cy)
  await mobile.mouse.down()
  await mobile.mouse.move(cx + 32, cy, { steps: 5 })
  await mobile.waitForTimeout(750)
  await mobile.mouse.up()
  await mobile.waitForTimeout(250)
}
const mobileMoved = await mobile.evaluate(() => window.__snackSafari.state.player)
const mobileTame = await tameOne(mobile)
const throwsBefore = (await mobile.evaluate(() => window.__snackSafari.state)).throws
await mobile.click('#toss-button')
await mobile.waitForTimeout(800)
const mobileAfter = await mobile.evaluate(() => window.__snackSafari.state)
console.log('MOBILE', JSON.stringify({
  deltaX: Math.round(mobileMoved.x - mobileStart.player.x),
  tame: mobileTame,
  throwsBefore,
  throwsAfter: mobileAfter.throws,
  crew: mobileAfter.crew,
}))
await mobile.waitForTimeout(600)
await mobile.screenshot({ path: '/home/runner/work/Throwfood/Throwfood/screenshots/play-mobile.png' })

console.log('ERRORS', JSON.stringify(errors))
await browser.close()

