import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => window.__snackSafari?.state)
await page.waitForTimeout(500)
await page.evaluate(() => { const a = window.__snackSafari; a.player.x = 355; a.player.y = 790; })
await page.waitForTimeout(500)
const prompt = page.locator('#interaction-prompt')
const visible = await prompt.isVisible()
const label = (await prompt.textContent()).trim()
await prompt.click()
await page.waitForTimeout(350)
const shopOpen = await page.locator('#shop-modal').isVisible()
console.log(JSON.stringify({ visible, label, shopOpen }))
await page.screenshot({ path: '/tmp/opencode/mobile-shop.png' })
await browser.close()

